export const simulateTextOverflow = (element, scrollWidth, clientWidth) => {
    Object.defineProperty(element, "scrollWidth", {
        value: scrollWidth,
        configurable: true
    });
    Object.defineProperty(element, "clientWidth", {
        value: clientWidth,
        configurable: true
    })
};
export const simulateHoverEvent = (element, options) => {
    element.dispatchEvent(new MouseEvent("mousemove", options ?? {
        bubbles: true,
        cancelable: true
    }))
};
